//! ACES 1.2 against OpenColorIO, both directions, CPU and GPU: wobble's
//! `engine/tests/aces12.rs` over Scrub's copy, on the same numbers.
//!
//! `engine/tests/aces12_ref/tables.rs` is generated by `tools/aces12_reference.py`. The
//! `ANALYTIC_*` tables are OCIO's built-in ACES transforms, the CTL in closed
//! form, and are held tightly. The `LUT_*` tables are an ACES 1.2 config's
//! baked Output LUTs, which only approximate that maths: a few rows differ
//! by far more than the rest (a channel the rendering clips to zero comes
//! back from the cube as 0.07; the sRGB inverse's toe is coarse), so those
//! are counted, not bounded. GPU tests self-skip without an adapter.

use colour::color::{Colorspace, Transform};

mod tables {
    #![allow(clippy::excessive_precision)]
    include!("../../../engine/tests/aces12_ref/tables.rs");
}
use tables::*;

type Table = &'static [([f32; 3], [f32; 3])];

const FWD: [(&str, Colorspace, Table, Table); 2] = [
    ("Rec.709", Colorspace::ACES_OUTPUT_REC709, ANALYTIC_FWD_REC709, LUT_FWD_REC709),
    ("sRGB", Colorspace::ACES_OUTPUT_SRGB, ANALYTIC_FWD_SRGB, LUT_FWD_SRGB),
];
const INV: [(&str, Colorspace, Table, Table); 2] = [
    ("Rec.709", Colorspace::ACES_OUTPUT_REC709, ANALYTIC_INV_REC709, LUT_INV_REC709),
    ("sRGB", Colorspace::ACES_OUTPUT_SRGB, ANALYTIC_INV_SRGB, LUT_INV_SRGB),
];

fn forward(cs: Colorspace) -> Transform {
    Transform::new(Colorspace::ACESCG, cs)
}
fn inverse(cs: Colorspace) -> Transform {
    Transform::new(cs, Colorspace::ACESCG)
}

/// Worst absolute error, per channel.
fn worst_abs(got: &[[f32; 3]], t: Table) -> f32 {
    got.iter().zip(t).flat_map(|(g, (_, w))| (0..3).map(move |k| (g[k] - w[k]).abs())).fold(0.0, f32::max)
}

/// Worst error relative to the pixel's brightest channel: scene-linear
/// values span five decades, so an absolute figure would only see the top.
fn worst_rel(got: &[[f32; 3]], t: Table) -> f32 {
    got.iter()
        .zip(t)
        .flat_map(|(g, (_, w))| {
            let m = w[0].max(w[1]).max(w[2]).max(0.01);
            (0..3).map(move |k| (g[k] - w[k]).abs() / m)
        })
        .fold(0.0, f32::max)
}

/// Rows off by more than `tol`, by `err`'s measure.
fn outliers(got: &[[f32; 3]], t: Table, tol: f32, err: fn(&[[f32; 3]], Table) -> f32) -> usize {
    (0..t.len()).filter(|&i| err(&got[i..=i], &t[i..=i]) > tol).count()
}

fn cpu(t: Transform, table: Table) -> Vec<[f32; 3]> {
    table.iter().map(|(i, _)| t.apply(*i)).collect()
}

#[test]
fn forward_matches_ocio() {
    for (name, cs, analytic, lut) in FWD {
        let e = worst_abs(&cpu(forward(cs), analytic), analytic);
        let got = cpu(forward(cs), lut);
        let l = worst_abs(&got, lut);
        let off = outliers(&got, lut, 4e-3, worst_abs);
        eprintln!("{name} view, CPU: analytic {e:.6}, config LUT {l:.6} ({off} rows past 0.004)");
        assert!(e < 1e-3, "{name}: {e}");
        assert!(off <= 3, "{name} against the LUT: {off} rows");
    }
}

#[test]
fn inverse_matches_ocio() {
    for (name, cs, analytic, lut) in INV {
        let e = worst_rel(&cpu(inverse(cs), analytic), analytic);
        let got = cpu(inverse(cs), lut);
        let l = worst_rel(&got, lut);
        let off = outliers(&got, lut, 1e-2, worst_rel);
        eprintln!("{name} input, CPU: analytic {e:.6}, config LUT {l:.6} ({off} rows past 1%)");
        assert!(e < 2e-3, "{name}: {e}");
        assert!(off <= 1, "{name} against the LUT: {off} rows");
    }
}

/// A display value in the renderable range survives input -> view.
#[test]
fn input_then_view_returns_the_codes() {
    for (name, cs, ..) in INV {
        let (inv, fwd) = (inverse(cs), forward(cs));
        let (mut worst, mut at, mut past) = (0.0f32, [0.0; 3], 0);
        for i in 0..=20 {
            for j in 0..=20 {
                for k in 0..=20 {
                    // Inside the range the rendering can reach in every
                    // channel: its own clipped corners do not come back.
                    let c = [i, j, k].map(|v| 0.1 + 0.8 * v as f32 / 20.0);
                    let back = fwd.apply(inv.apply(c));
                    let e = (0..3).map(|n| (back[n] - c[n]).abs()).fold(0.0, f32::max);
                    past += (e > 1e-3) as u32;
                    if e > worst {
                        (worst, at) = (e, c);
                    }
                }
            }
        }
        eprintln!("{name}: round trip worst {worst:.6} at {at:?}, {past} of 9261 past 0.001");
        // The CTL's inverse is itself inexact for saturated colours (its red
        // modifier and glow solve for a saturation they cannot know).
        assert!(worst < 0.01, "{name}: {worst} at {at:?}");
    }
    // Greys are the promise that holds all the way to display white.
    for (name, cs, ..) in INV {
        let (inv, fwd) = (inverse(cs), forward(cs));
        for i in 0..=255 {
            let v = i as f32 / 255.0;
            let back = fwd.apply(inv.apply([v; 3]));
            for n in 0..3 {
                assert!((back[n] - v).abs() < 1e-3, "{name} grey {v}: {back:?}");
            }
        }
    }
}

// --- GPU --------------------------------------------------------------------

/// Run `t`'s generated WGSL over the table's inputs in a compute pass.
fn gpu(ctx: &Ctx, t: Transform, table: Table) -> Vec<[f32; 3]> {
    use wgpu::util::DeviceExt;
    let mut helpers = std::collections::BTreeMap::new();
    let f = t.wgsl("cs_test", &mut helpers);
    let mut src: String = helpers.values().cloned().collect();
    src.push_str(&f);
    src.push_str(
        "@group(0) @binding(0) var<storage, read_write> px: array<vec4f>;
         @compute @workgroup_size(1) fn main(@builtin(global_invocation_id) id: vec3u) {
             px[id.x] = vec4f(cs_test(px[id.x].rgb), 1.0);
         }",
    );
    let d = &ctx.device;
    let module = d.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: None,
        source: wgpu::ShaderSource::Wgsl(src.into()),
    });
    let pipe = d.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: None,
        layout: None,
        module: &module,
        entry_point: Some("main"),
        compilation_options: Default::default(),
        cache: None,
    });
    let data: Vec<[f32; 4]> = table.iter().map(|(i, _)| [i[0], i[1], i[2], 1.0]).collect();
    let buf = d.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: None,
        contents: bytemuck::cast_slice(&data),
        usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC,
    });
    let size = buf.size();
    let read = d.create_buffer(&wgpu::BufferDescriptor {
        label: None,
        size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });
    let bind = d.create_bind_group(&wgpu::BindGroupDescriptor {
        label: None,
        layout: &pipe.get_bind_group_layout(0),
        entries: &[wgpu::BindGroupEntry { binding: 0, resource: buf.as_entire_binding() }],
    });
    let mut enc = d.create_command_encoder(&Default::default());
    {
        let mut pass = enc.begin_compute_pass(&Default::default());
        pass.set_pipeline(&pipe);
        pass.set_bind_group(0, &bind, &[]);
        pass.dispatch_workgroups(data.len() as u32, 1, 1);
    }
    enc.copy_buffer_to_buffer(&buf, 0, &read, 0, size);
    ctx.queue.submit([enc.finish()]);
    let (tx, rx) = std::sync::mpsc::channel();
    read.slice(..).map_async(wgpu::MapMode::Read, move |r| {
        let _ = tx.send(r);
    });
    let _ = d.poll(wgpu::PollType::wait_indefinitely());
    rx.recv().unwrap().unwrap();
    let bytes = read.slice(..).get_mapped_range().expect("a mapped buffer");
    bytemuck::cast_slice::<u8, [f32; 4]>(&bytes).iter().map(|p| [p[0], p[1], p[2]]).collect()
}

struct Ctx {
    device: wgpu::Device,
    queue: wgpu::Queue,
}

fn ctx() -> Option<Ctx> {
    let instance = wgpu::Instance::new(wgpu::InstanceDescriptor::new_without_display_handle_from_env());
    let adapter = match pollster::block_on(instance.request_adapter(&Default::default())) {
        Ok(a) => a,
        Err(e) => {
            eprintln!("SKIP aces12 GPU test: no adapter ({e})");
            return None;
        }
    };
    let (device, queue) = pollster::block_on(adapter.request_device(&Default::default())).ok()?;
    Some(Ctx { device, queue })
}

#[test]
fn shader_forward_matches_ocio() {
    let Some(ctx) = ctx() else { return };
    for (name, cs, analytic, _) in FWD {
        let e = worst_abs(&gpu(&ctx, forward(cs), analytic), analytic);
        eprintln!("{name} view, GPU: analytic {e:.6} (code values)");
        assert!(e < 1e-3, "{name}: {e}");
    }
}

#[test]
fn shader_inverse_matches_ocio() {
    let Some(ctx) = ctx() else { return };
    for (name, cs, analytic, _) in INV {
        let e = worst_rel(&gpu(&ctx, inverse(cs), analytic), analytic);
        eprintln!("{name} input, GPU: analytic {e:.6} (of the pixel's peak)");
        assert!(e < 2e-3, "{name}: {e}");
    }
}

